// Local-presence area codes per state pool (primary first). Extend as pools open.
const AREA = {
  AL:['205','251'], AK:['907'], AZ:['602','480'], AR:['501','479'], CA:['213','415','619'],
  CO:['303','719'], CT:['203','860'], DE:['302'], FL:['305','407','813'], GA:['404','678'],
  HI:['808'], ID:['208'], IL:['312','773'], IN:['317'], IA:['515'], KS:['316','913'],
  KY:['502','859'], LA:['504','225'], ME:['207'], MD:['410','301'], MA:['617','508'],
  MI:['313','616'], MN:['612','651'], MS:['601'], MO:['314','816'], MT:['406'], NE:['402'],
  NV:['702','775'], NH:['603'], NJ:['201','732'], NM:['505'], NY:['212','718','516'],
  NC:['704','919'], ND:['701'], OH:['614','216'], OK:['405','918'], OR:['503'],
  PA:['215','412'], RI:['401'], SC:['803','843'], SD:['605'], TN:['615','901'],
  // TX order: 469/972/817 verified in-stock via live API 2026-07-26; 214 was dry.
  TX:['469','972','817','214','512','713'], UT:['801'], VT:['802'], VA:['703','804'], WA:['206','253'],
  WV:['304'], WI:['414','608'], WY:['307']
};
const b = $json.body ?? $json;
const state = String(b.state || '').toUpperCase().trim();
const codes = AREA[state] || [];
// Random 16-char seat password; rep resets it on first login.
const pw = Array.from(crypto.getRandomValues(new Uint32Array(16)), n => 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789'.charAt(n % 55)).join('');
return [{ json: {
  first_name: b.first_name, last_name: b.last_name || '', email: b.email,
  phone: b.phone || '', state, partner_code: b.partner_code || '',
  area_primary: codes[0] || '', area_fallbacks: codes.slice(1), seat_password: pw,
}}];

// Pick the first available number; surface a clear error if the area code is dry.
const prep = $('Prep — Area Codes + Seat Password').first().json;
const list = $json.numbers ?? $json.data ?? (Array.isArray($json) ? $json : []);
const pick = Array.isArray(list) && list.length ? (list[0].phoneNumber ?? list[0].number ?? list[0]) : null;
if (!pick) {
  throw new Error(`No local numbers available for area code ${prep.area_primary} (state ${prep.state}). Re-run with a fallback code: ${prep.area_fallbacks.join(', ') || 'none mapped'} — or buy manually in Settings → Phone Numbers.`);
}
return [{ json: { ...prep, chosen_number: typeof pick === 'string' ? pick : String(pick) } }];

